#define WEBP_FALLTHROUGH
#endif
#endif /* WEBP_FALLTHROUGH */

// Macro to check ABI compatibility (same major revision number)
#define WEBP_ABI_IS_INCOMPATIBLE(a, b) (((a) >> 8) != ((b) >> 8))

